// Số lượng frame
const int total_frames = 76; 
int current_frame = 1;
int direction = 1;

void setup() {
  Serial.begin(115200);

  // Khởi động OLED tại địa chỉ 0x3C
  if(!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) { 
    Serial.println(F("Không tìm thấy màn hình OLED"));
    for(;;); // Lặp vô hạn nếu lỗi
  }

  display.clearDisplay();
}

void loop() {
  display.clearDisplay();

  // Hiển thị frame hiện tại
  display.drawBitmap(0, 0, epd_bitmap_allArray[current_frame], 128, 64, WHITE);
  
  display.display(); // Đẩy dữ liệu ra màn hình

  // Tăng hoặc giảm frame dựa theo biến direction
  current_frame = current_frame + direction;

  // KIỂM TRA ĐIỀU KIỆN ĐỂ QUAY ĐẦU
  if (current_frame >= total_frames - 1) {
    // Nếu chạm đến frame cuối cùng (80) -> Đảo chiều thành lùi
    direction = -1; 
  } 
  else if (current_frame <= 1) {
    // Nếu lùi về đến frame đầu tiên (0) -> Đảo chiều thành tiến
    direction = 1; 
  }

  delay(30); 
}